from decimal import Decimal

import pytest

from pricing import split_amount


def test_split_amount_ten_into_three_puts_larger_parts_first():
    assert split_amount(Decimal("10.00"), 3) == [
        Decimal("3.34"),
        Decimal("3.33"),
        Decimal("3.33"),
    ]


def test_split_amount_even_split_gives_equal_parts():
    assert split_amount(Decimal("9"), 3) == [
        Decimal("3.00"),
        Decimal("3.00"),
        Decimal("3.00"),
    ]


def test_split_amount_one_cent_into_two_parts_gives_the_cent_to_one_part():
    assert split_amount(Decimal("0.01"), 2) == [Decimal("0.01"), Decimal("0.00")]


def test_split_amount_rejects_zero_parts():
    with pytest.raises(ValueError):
        split_amount(Decimal("5"), 0)


def test_split_amount_rejects_negative_amount():
    with pytest.raises(ValueError):
        split_amount(Decimal("-1"), 2)

