from decimal import ROUND_HALF_UP, Decimal

_CENT = Decimal("0.01")


def split_amount(amount: Decimal, parts: int) -> list[Decimal]:
    if parts < 1:
        raise ValueError("parts must be at least 1")
    if amount < 0:
        raise ValueError("amount must not be negative")

    total_cents = int(amount.quantize(_CENT, rounding=ROUND_HALF_UP) * 100)
    base_cents, remainder = divmod(total_cents, parts)

    return [
        Decimal(base_cents + (1 if index < remainder else 0)).scaleb(-2)
        for index in range(parts)
    ]

